CREATE OR REPLACE FUNCTION core10._append_canonical_audit_v1(p_tenant bigint, p_business bigint, p_source text, p_ref text, p_action text, p_actor uuid, p_key text, p_payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE h core10.audit_chain_heads_v1%ROWTYPE;
 old core10.canonical_audit_events_v1%ROWTYPE;
 v_sha text;v_digest text;v_seq bigint;v_at timestamptz;v_id bigint;
BEGIN
 IF p_tenant IS NULL OR p_business IS NULL OR p_actor IS NULL
  OR p_source IS NULL OR p_source !~ '^[a-z][a-z0-9_]{1,63}$'
  OR p_ref IS NULL OR length(p_ref) NOT BETWEEN 1 AND 120
  OR p_action IS NULL OR p_action !~ '^[a-z][a-z0-9_.]{1,100}$'
  OR p_key IS NULL OR length(p_key) NOT BETWEEN 1 AND 160
  OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object'
  OR NOT EXISTS(SELECT 1 FROM core10.businesses b
     WHERE b.id=p_business AND b.tenant_id=p_tenant)
 THEN RAISE EXCEPTION 'canonical_audit_invalid_source'; END IF;
 v_sha:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');
 INSERT INTO core10.audit_chain_heads_v1(tenant_id,business_id)
 VALUES(p_tenant,p_business) ON CONFLICT(business_id) DO NOTHING;
 SELECT * INTO h FROM core10.audit_chain_heads_v1 WHERE business_id=p_business FOR UPDATE;
 IF h.tenant_id<>p_tenant THEN RAISE EXCEPTION 'canonical_audit_scope_mismatch'; END IF;
 SELECT * INTO old FROM core10.canonical_audit_events_v1
 WHERE business_id=p_business AND source_domain=p_source AND source_ref=p_ref;
 IF FOUND THEN
  IF old.actor_id<>p_actor OR old.request_key<>p_key OR old.action<>p_action
     OR old.payload_sha256<>v_sha OR old.tenant_id<>p_tenant
  THEN RAISE EXCEPTION 'canonical_audit_replay_conflict'; END IF;
  RETURN old.id;
 END IF;
 v_seq:=h.last_seq+1;v_at:=clock_timestamp();
 v_digest:=encode(sha256(convert_to(concat_ws('|',
  'c10-audit-v1',h.last_digest,p_tenant::text,p_business::text,v_seq::text,
  p_source,p_ref,p_action,p_actor::text,p_key,v_sha,
  to_char(v_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),'UTF8')),'hex');
 INSERT INTO core10.canonical_audit_events_v1(
  tenant_id,business_id,stream_seq,source_domain,source_ref,action,
  actor_id,request_key,payload,payload_sha256,prior_digest,event_digest,event_at)
 VALUES(p_tenant,p_business,v_seq,p_source,p_ref,p_action,p_actor,p_key,
        p_payload,v_sha,h.last_digest,v_digest,v_at)
 RETURNING id INTO v_id;
 UPDATE core10.audit_chain_heads_v1 SET last_seq=v_seq,last_digest=v_digest
 WHERE business_id=p_business;
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION core10.actor_uid()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE claims jsonb; uid uuid; sid uuid; valid_session boolean;
BEGIN
 claims:=COALESCE(NULLIF(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb);
 BEGIN
  uid:=COALESCE(NULLIF(claims->>'sub',''),NULLIF(current_setting('request.jwt.claim.sub',true),''))::uuid;
 EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END;
 IF uid IS NULL THEN RETURN NULL; END IF;
 IF to_regclass('auth.sessions') IS NOT NULL THEN
  BEGIN sid:=NULLIF(claims->>'session_id','')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END;
  IF sid IS NULL OR to_regclass('auth.users') IS NULL THEN RETURN NULL; END IF;
  EXECUTE 'SELECT EXISTS(SELECT 1 FROM auth.sessions s JOIN auth.users u ON u.id=s.user_id
   WHERE s.id=$1 AND s.user_id=$2 AND (s.not_after IS NULL OR s.not_after>statement_timestamp())
    AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until<=statement_timestamp()))'
   INTO valid_session USING sid,uid;
  IF NOT valid_session THEN RETURN NULL; END IF;
 END IF;
 RETURN uid;
END $function$

CREATE OR REPLACE FUNCTION core10.build01_set_access_v1(p_business bigint, p_subject uuid, p_command text, p_role text, p_site bigint, p_actions text[], p_denied_actions text[], p_valid_until timestamp with time zone, p_request text, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE actor uuid:=core10.actor_uid(); tenant bigint; signature jsonb; previous record; before_state jsonb; after_state jsonb;
 event_id bigint; base_event bigint; current_version bigint; known_subject boolean; desired text[]:=COALESCE(p_actions,'{}'::text[]);
 denied text[]:=COALESCE(p_denied_actions,'{}'::text[]); membership_role text;
BEGIN
 SELECT tenant_id INTO tenant FROM core10.businesses WHERE id=p_business;
 IF actor IS NULL OR tenant IS NULL OR NOT core10.can_manage(tenant,p_business) THEN RAISE EXCEPTION 'BUILD01_ACCESS_DENIED'; END IF;
 IF p_subject IS NULL OR p_subject=actor THEN RAISE EXCEPTION 'BUILD01_SELF_ACCESS_CHANGE_FORBIDDEN'; END IF;
 IF p_command IS NULL OR p_command NOT IN('business_member.grant','business_member.revoke','site_grant.grant','site_grant.revoke') OR
  p_request IS NULL OR length(btrim(p_request)) NOT BETWEEN 1 AND 120 OR p_expected_version<0 THEN RAISE EXCEPTION 'BUILD01_INVALID_ACCESS'; END IF;
 IF NOT denied <@ ARRAY['stock.read','stock.post']::text[] OR cardinality(denied)<>(SELECT count(DISTINCT x) FROM unnest(denied)x) OR
  NOT desired <@ ARRAY['stock.read','stock.post']::text[] OR cardinality(desired)<>(SELECT count(DISTINCT x) FROM unnest(desired)x)
 THEN RAISE EXCEPTION 'BUILD01_INVALID_ACTIONS'; END IF;
 IF p_command LIKE 'business_member.%' AND (p_site IS NOT NULL OR cardinality(desired)>0 OR cardinality(denied)>0) THEN RAISE EXCEPTION 'BUILD01_INVALID_MEMBERSHIP'; END IF;
 IF p_command LIKE 'site_grant.%' AND (p_site IS NULL OR p_role IS NOT NULL) THEN RAISE EXCEPTION 'BUILD01_INVALID_SITE_POLICY'; END IF;
 IF p_command LIKE '%.revoke' AND (p_valid_until IS NOT NULL OR cardinality(desired)>0 OR cardinality(denied)>0 OR p_role IS NOT NULL) THEN RAISE EXCEPTION 'BUILD01_INVALID_REVOKE'; END IF;
 IF p_command='site_grant.grant' AND cardinality(desired)=0 AND cardinality(denied)=0 THEN RAISE EXCEPTION 'BUILD01_EMPTY_POLICY'; END IF;
 IF to_regclass('auth.users') IS NOT NULL THEN
  EXECUTE 'SELECT EXISTS(SELECT 1 FROM auth.users WHERE id=$1 AND deleted_at IS NULL)' INTO known_subject USING p_subject;
 ELSE
  SELECT EXISTS(SELECT 1 FROM core10.tenant_members WHERE user_id=p_subject) OR
   EXISTS(SELECT 1 FROM core10.business_members WHERE user_id=p_subject) OR
   EXISTS(SELECT 1 FROM core10.site_grants WHERE user_id=p_subject) INTO known_subject;
 END IF;
 IF NOT known_subject THEN RAISE EXCEPTION 'BUILD01_SUBJECT_NOT_REGISTERED'; END IF;
 PERFORM 1 FROM core10.businesses WHERE id=p_business FOR UPDATE;
 IF NOT core10.can_manage(tenant,p_business) THEN RAISE EXCEPTION 'BUILD01_ACCESS_DENIED'; END IF;
 SELECT role INTO membership_role FROM core10.business_members WHERE business_id=p_business AND user_id=p_subject AND active;
 IF membership_role='business_owner' AND NOT core10.can_tenant(tenant) THEN RAISE EXCEPTION 'BUILD01_BUSINESS_OWNER_PROTECTED'; END IF;
 IF p_command LIKE 'site_grant.%' THEN
  IF NOT EXISTS(SELECT 1 FROM core10.sites WHERE id=p_site AND business_id=p_business AND tenant_id=tenant) THEN RAISE EXCEPTION 'BUILD01_SITE_SCOPE_MISMATCH'; END IF;
  IF membership_role='investor' THEN RAISE EXCEPTION 'investor_cannot_receive_stock_grant'; END IF;
  SELECT to_jsonb(g),g.version INTO before_state,current_version FROM core10.site_grants g WHERE site_id=p_site AND user_id=p_subject;
 ELSE
  SELECT to_jsonb(m),m.version INTO before_state,current_version FROM core10.business_members m WHERE business_id=p_business AND user_id=p_subject;
  before_state:=COALESCE(before_state,'{}')||jsonb_build_object('site_grants',COALESCE((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.site_id) FROM core10.site_grants g WHERE g.business_id=p_business AND g.user_id=p_subject),'[]'::jsonb));
 END IF;
 signature:=jsonb_build_object('business',p_business,'subject',p_subject,'command',p_command,'role',p_role,'site',p_site,
  'actions',desired,'denied_actions',denied,'valid_until',p_valid_until,'expected_version',p_expected_version);
 SELECT * INTO previous FROM core10.access_change_events_v1 WHERE business_id=p_business AND request_key=p_request;
 IF FOUND THEN
  IF previous.input_signature<>signature OR previous.actor_uid<>actor OR previous.event_kind<>'policy.apply' THEN RAISE EXCEPTION 'BUILD01_REQUEST_CONFLICT'; END IF;
  RETURN jsonb_build_object('business_id',p_business,'event_id',previous.id,'request_key',p_request,'after_state',previous.after_state);
 END IF;
 IF p_valid_until IS NOT NULL AND p_valid_until<=statement_timestamp() THEN RAISE EXCEPTION 'BUILD01_EXPIRY_MUST_BE_FUTURE'; END IF;
 IF p_expected_version IS NOT NULL AND p_expected_version<>COALESCE(current_version,0) THEN RAISE EXCEPTION 'BUILD01_STALE_ACCESS_VERSION'; END IF;
 -- Deny-only policies must not silently grant read access just to satisfy the
 -- legacy A034 nonempty-actions command. All other base changes delegate A034.
 IF p_command='site_grant.grant' AND cardinality(desired)=0 THEN
  INSERT INTO core10.site_grants(tenant_id,business_id,site_id,user_id,actions,active,valid_until,denied_actions)
  VALUES(tenant,p_business,p_site,p_subject,'{}',true,p_valid_until,denied)
  ON CONFLICT(site_id,user_id) DO UPDATE SET actions='{}',active=true,valid_until=EXCLUDED.valid_until,denied_actions=EXCLUDED.denied_actions;
 ELSE
  base_event:=core10.change_access_v1(p_business,p_subject,p_command,p_role,p_site,desired,'build01-base:'||md5(p_request));
  IF p_command='site_grant.grant' THEN
   UPDATE core10.site_grants SET valid_until=p_valid_until,denied_actions=denied
    WHERE site_id=p_site AND user_id=p_subject AND (valid_until IS DISTINCT FROM p_valid_until OR denied_actions IS DISTINCT FROM denied);
  ELSIF p_command='business_member.grant' THEN
   UPDATE core10.business_members SET valid_until=p_valid_until WHERE business_id=p_business AND user_id=p_subject AND valid_until IS DISTINCT FROM p_valid_until;
  ELSIF p_command='business_member.revoke' THEN
   -- Build01's business revoke removes all this subject's business site grants
   -- atomically too; the policy receipt records every affected canonical row.
   UPDATE core10.site_grants SET active=false WHERE business_id=p_business AND user_id=p_subject AND active;
  END IF;
 END IF;
 IF p_command LIKE 'site_grant.%' THEN
  SELECT to_jsonb(g) INTO after_state FROM core10.site_grants g WHERE site_id=p_site AND user_id=p_subject;
 ELSE
  SELECT to_jsonb(m) INTO after_state FROM core10.business_members m WHERE business_id=p_business AND user_id=p_subject;
  after_state:=after_state||jsonb_build_object('site_grants',COALESCE((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.site_id) FROM core10.site_grants g WHERE g.business_id=p_business AND g.user_id=p_subject),'[]'::jsonb));
 END IF;
 INSERT INTO core10.access_change_events_v1(tenant_id,business_id,request_key,command,subject_uid,site_id,desired_role,desired_actions,input_signature,before_state,after_state,actor_uid,event_kind)
 VALUES(tenant,p_business,p_request,p_command,p_subject,p_site,p_role,NULLIF(desired,'{}'),signature,COALESCE(before_state,'{}'),after_state,actor,'policy.apply') RETURNING id INTO event_id;
 RETURN jsonb_build_object('business_id',p_business,'event_id',event_id,'request_key',p_request,'after_state',after_state);
END $function$

CREATE OR REPLACE FUNCTION core10.build01_setup_v1(p_legal bigint, p_slug text, p_template text, p_display_name text, p_mode text, p_sites jsonb, p_request text, p_brand_hex text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE business bigint; tenant bigint; actor uuid:=core10.actor_uid(); signature jsonb; previous record; event_id bigint; modules jsonb;
BEGIN
 SELECT tenant_id INTO tenant FROM core10.legal_entities WHERE id=p_legal;
 IF actor IS NULL OR tenant IS NULL OR NOT core10.can_tenant(tenant) THEN RAISE EXCEPTION 'BUILD01_SETUP_DENIED'; END IF;
 -- Original setup engines perform multiple canonical inserts. Serialize the
 -- same tenant/request before entering either engine so concurrent retries
 -- observe the committed receipt instead of racing the unique slug constraint.
 PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array('build01.setup',tenant,p_request)::text,0));
 IF NOT core10.can_tenant(tenant) THEN RAISE EXCEPTION 'BUILD01_SETUP_DENIED'; END IF;
 -- Reuse the original ten-family draft engine. Module selections come only
 -- from its canonical catalog; that engine keeps every module locked/disabled.
 -- Legacy demo-approved template codes retain the existing A020 v1 contract.
 IF EXISTS(SELECT 1 FROM core10.industry_catalog_v2 WHERE id=p_template) THEN
  SELECT COALESCE(jsonb_agg(module_code ORDER BY module_code),'[]'::jsonb) INTO modules
   FROM core10.industry_module_catalog_v2 WHERE industry_id=p_template;
  business:=core10.setup_industry_draft_v2(p_legal,p_slug,p_template,p_display_name,p_mode,p_sites,modules,p_request,p_brand_hex);
 ELSE
  business:=core10.setup_business_v1(p_legal,p_slug,p_template,p_display_name,p_mode,p_sites,p_request,p_brand_hex);
 END IF;
 signature:=jsonb_build_object('legal',p_legal,'slug',p_slug,'template',p_template,'display_name',p_display_name,'mode',p_mode,'sites',p_sites,'request',p_request,'brand_hex',p_brand_hex);
 SELECT * INTO previous FROM core10.access_change_events_v1 WHERE business_id=business AND request_key=p_request;
 IF FOUND THEN
  IF previous.input_signature<>signature OR previous.actor_uid<>actor OR previous.event_kind<>'setup.business' THEN RAISE EXCEPTION 'BUILD01_REQUEST_CONFLICT'; END IF;
  event_id:=previous.id;
 ELSE
  INSERT INTO core10.access_change_events_v1(tenant_id,business_id,request_key,command,subject_uid,input_signature,before_state,after_state,actor_uid,event_kind)
   VALUES(tenant,business,p_request,'setup.business',actor,signature,'{}',jsonb_build_object('business_id',business,'status','draft'),actor,'setup.business') RETURNING id INTO event_id;
 END IF;
 RETURN jsonb_build_object('business_id',business,'request_key',p_request,'event_id',event_id,'status','draft','production_certified',false);
END $function$

CREATE OR REPLACE FUNCTION core10.build01_site_v1(p_business bigint, p_kind text, p_label text, p_request text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE site bigint; tenant bigint; actor uuid:=core10.actor_uid(); signature jsonb; previous record; event_id bigint;
BEGIN
 SELECT tenant_id INTO tenant FROM core10.businesses WHERE id=p_business;
 IF actor IS NULL OR tenant IS NULL OR NOT core10.can_manage(tenant,p_business) THEN RAISE EXCEPTION 'BUILD01_SITE_DENIED'; END IF;
 PERFORM 1 FROM core10.businesses WHERE id=p_business FOR UPDATE;
 IF NOT core10.can_manage(tenant,p_business) THEN RAISE EXCEPTION 'BUILD01_SITE_DENIED'; END IF;
 signature:=jsonb_build_object('business',p_business,'kind',p_kind,'label',p_label,'request',p_request);
 SELECT * INTO previous FROM core10.access_change_events_v1 WHERE business_id=p_business AND request_key=p_request;
 IF FOUND THEN
  IF previous.input_signature<>signature OR previous.actor_uid<>actor OR previous.event_kind<>'setup.site' THEN RAISE EXCEPTION 'BUILD01_REQUEST_CONFLICT'; END IF;
  RETURN previous.after_state||jsonb_build_object('event_id',previous.id,'request_key',p_request);
 END IF;
 site:=core10.provision_site(p_business,p_kind,p_label,p_request);
 INSERT INTO core10.access_change_events_v1(tenant_id,business_id,request_key,command,subject_uid,site_id,input_signature,before_state,after_state,actor_uid,event_kind)
 VALUES(tenant,p_business,p_request,'setup.site',actor,site,signature,'{}',jsonb_build_object('business_id',p_business,'site_id',site),actor,'setup.site') RETURNING id INTO event_id;
 RETURN jsonb_build_object('business_id',p_business,'site_id',site,'request_key',p_request,'event_id',event_id);
END $function$

CREATE OR REPLACE FUNCTION core10.build02a_set_approval_policy_v1(p_business bigint, p_subject uuid, p_actions text[], p_denied_actions text[], p_valid_until timestamp with time zone, p_request text, p_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE actor uuid:=core10.actor_uid(); tenant bigint; member record; previous record; event_id bigint;
 desired text[]:=COALESCE(p_actions,'{}'::text[]); denied text[]:=COALESCE(p_denied_actions,'{}'::text[]); signature jsonb; after_state jsonb;
BEGIN
 SELECT tenant_id INTO tenant FROM core10.businesses WHERE id=p_business;
 IF actor IS NULL OR tenant IS NULL OR NOT core10.can_manage(tenant,p_business) THEN RAISE EXCEPTION 'BUILD02A_POLICY_DENIED'; END IF;
 IF p_subject IS NULL OR p_subject=actor OR p_request IS NULL OR length(btrim(p_request)) NOT BETWEEN 1 AND 120 OR p_expected_version<0 THEN
  RAISE EXCEPTION 'BUILD02A_INVALID_POLICY';
 END IF;
 IF NOT desired <@ ARRAY['approval.submit','approval.decide','approval.delegate','approval.withdraw','approval.export','approval.exception']::text[]
  OR NOT denied <@ ARRAY['approval.submit','approval.decide','approval.delegate','approval.withdraw','approval.export','approval.exception']::text[]
  OR cardinality(desired)<>(SELECT count(DISTINCT x) FROM unnest(desired)x)
  OR cardinality(denied)<>(SELECT count(DISTINCT x) FROM unnest(denied)x)
  OR EXISTS(SELECT 1 FROM unnest(desired)x WHERE x=ANY(denied)) THEN RAISE EXCEPTION 'BUILD02A_INVALID_ACTIONS'; END IF;
 IF p_valid_until IS NOT NULL AND p_valid_until<=statement_timestamp() THEN RAISE EXCEPTION 'BUILD02A_EXPIRY_MUST_BE_FUTURE'; END IF;
 PERFORM 1 FROM core10.businesses WHERE id=p_business FOR UPDATE;
 IF NOT core10.can_manage(tenant,p_business) THEN RAISE EXCEPTION 'BUILD02A_POLICY_DENIED'; END IF;
 SELECT * INTO member FROM core10.business_members WHERE business_id=p_business AND user_id=p_subject FOR UPDATE;
 IF NOT FOUND OR NOT member.active OR (member.valid_until IS NOT NULL AND member.valid_until<=statement_timestamp()) OR member.role='investor' THEN
  RAISE EXCEPTION 'BUILD02A_SUBJECT_NOT_ELIGIBLE';
 END IF;
 signature:=jsonb_build_object('business',p_business,'subject',p_subject,'actions',desired,'denied_actions',denied,
  'valid_until',p_valid_until,'expected_version',p_expected_version);
 SELECT * INTO previous FROM core10.access_change_events_v1 WHERE business_id=p_business AND request_key=p_request;
 IF FOUND THEN
  IF previous.input_signature<>signature OR previous.actor_uid<>actor OR previous.command<>'approval_policy.apply' THEN RAISE EXCEPTION 'BUILD02A_REQUEST_CONFLICT'; END IF;
  RETURN jsonb_build_object('business_id',p_business,'event_id',previous.id,'request_key',p_request,'after_state',previous.after_state);
 END IF;
 IF p_expected_version IS NOT NULL AND p_expected_version<>member.version THEN RAISE EXCEPTION 'BUILD02A_STALE_VERSION'; END IF;
 UPDATE core10.business_members SET approval_actions=desired,approval_denied_actions=denied,approval_valid_until=p_valid_until
  WHERE business_id=p_business AND user_id=p_subject;
 SELECT to_jsonb(m) INTO after_state FROM core10.business_members m WHERE m.business_id=p_business AND m.user_id=p_subject;
 INSERT INTO core10.access_change_events_v1(tenant_id,business_id,request_key,command,subject_uid,input_signature,before_state,after_state,actor_uid,event_kind)
 VALUES(tenant,p_business,p_request,'approval_policy.apply',p_subject,signature,to_jsonb(member),after_state,actor,'policy.apply') RETURNING id INTO event_id;
 RETURN jsonb_build_object('business_id',p_business,'event_id',event_id,'request_key',p_request,'after_state',after_state);
END $function$

CREATE OR REPLACE FUNCTION core10.change_access_v1(p_business bigint, p_subject uuid, p_command text, p_role text, p_site bigint, p_actions text[], p_request text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE v_tenant bigint; v_actor uuid; v_owner boolean;
 v_site_tenant bigint; v_site_business bigint;
 v_previous record; v_event bigint; v_before jsonb:='{}'::jsonb;
 v_after jsonb:='{}'::jsonb; v_input jsonb; v_subject_role text;
 v_actions text[]:=COALESCE(p_actions,ARRAY[]::text[]);
BEGIN
 v_actor:=core10.actor_uid();
 IF v_actor IS NULL OR p_business IS NULL OR p_subject IS NULL OR
    p_command IS NULL OR p_command NOT IN (
     'business_member.grant','business_member.revoke',
     'site_grant.grant','site_grant.revoke') OR
    p_request IS NULL OR length(btrim(p_request)) NOT BETWEEN 1 AND 120
 THEN RAISE EXCEPTION 'invalid_access_change'; END IF;
 IF p_command LIKE 'business_member.%' THEN
  IF p_site IS NOT NULL OR cardinality(v_actions)<>0 THEN
   RAISE EXCEPTION 'invalid_membership_payload'; END IF;
  IF p_command='business_member.grant' AND
     (p_role IS NULL OR p_role NOT IN('business_owner','manager','investor'))
  THEN RAISE EXCEPTION 'invalid_business_role'; END IF;
  IF p_command='business_member.revoke' AND p_role IS NOT NULL
  THEN RAISE EXCEPTION 'invalid_membership_payload'; END IF;
 ELSE
  IF p_site IS NULL OR p_role IS NOT NULL THEN
   RAISE EXCEPTION 'invalid_site_access_payload'; END IF;
  IF p_command='site_grant.grant' AND
   (cardinality(v_actions)<1 OR cardinality(v_actions)>2 OR
     NOT v_actions <@ ARRAY['stock.read','stock.post']::text[] OR
     (SELECT count(DISTINCT x) FROM unnest(v_actions) x)<>cardinality(v_actions))
  THEN RAISE EXCEPTION 'invalid_site_actions'; END IF;
  IF p_command='site_grant.revoke' AND cardinality(v_actions)<>0
  THEN RAISE EXCEPTION 'invalid_site_access_payload'; END IF;
 END IF;
 SELECT tenant_id INTO v_tenant FROM core10.businesses WHERE id=p_business;
 IF v_tenant IS NULL OR NOT core10.can_manage(v_tenant,p_business)
 THEN RAISE EXCEPTION 'access_change_not_authorized'; END IF;
 v_owner:=core10.can_tenant(v_tenant);
 IF p_subject=v_actor THEN RAISE EXCEPTION 'self_access_change_forbidden'; END IF;
 -- Serialize all membership changes per business; this also protects duplicate
 -- request keys under concurrent callers and role changes during approval.
 PERFORM 1 FROM core10.businesses WHERE id=p_business FOR UPDATE;
 IF p_command LIKE 'site_grant.%' THEN
  SELECT tenant_id,business_id INTO v_site_tenant,v_site_business
    FROM core10.sites WHERE id=p_site;
  IF v_site_tenant IS NULL OR v_site_tenant<>v_tenant OR v_site_business<>p_business
  THEN RAISE EXCEPTION 'site_business_scope_mismatch'; END IF;
 END IF;
 v_input:=jsonb_build_object('business',p_business,'subject',p_subject,
   'command',p_command,'role',p_role,'site',p_site,'actions',v_actions);
 SELECT id,input_signature,actor_uid INTO v_previous
 FROM core10.access_change_events_v1
 WHERE business_id=p_business AND request_key=p_request;
 IF FOUND THEN
  IF v_previous.input_signature<>v_input OR v_previous.actor_uid<>v_actor
  THEN RAISE EXCEPTION 'access_request_idempotency_conflict'; END IF;
  RETURN v_previous.id;
 END IF;

 IF p_command LIKE 'business_member.%' THEN
  -- Read existing membership state from the database, never a claimed role.
  SELECT role,active INTO v_previous
   FROM core10.business_members
   WHERE business_id=p_business AND user_id=p_subject;
  IF FOUND THEN
   v_before:=jsonb_build_object('role',v_previous.role,'active',v_previous.active);
  END IF;
  IF p_command='business_member.grant' THEN
   IF p_role='business_owner' AND NOT v_owner THEN
    RAISE EXCEPTION 'tenant_owner_required_for_business_owner_role'; END IF;
   IF NOT v_owner AND v_previous.role='business_owner' THEN
    RAISE EXCEPTION 'business_owner_membership_protected'; END IF;
   INSERT INTO core10.business_members(tenant_id,business_id,user_id,role,active)
   VALUES(v_tenant,p_business,p_subject,p_role,true)
   ON CONFLICT(business_id,user_id) DO UPDATE
    SET role=EXCLUDED.role,active=true;
  ELSE
   IF v_before='{}'::jsonb OR NOT v_previous.active THEN
    RAISE EXCEPTION 'membership_not_active'; END IF;
   IF v_previous.role='business_owner' AND NOT v_owner THEN
    RAISE EXCEPTION 'business_owner_membership_protected'; END IF;
   UPDATE core10.business_members SET active=false
    WHERE business_id=p_business AND user_id=p_subject;
  END IF;
  SELECT jsonb_build_object('role',role,'active',active) INTO v_after
   FROM core10.business_members WHERE business_id=p_business AND user_id=p_subject;
 ELSE
  SELECT role INTO v_subject_role FROM core10.business_members
   WHERE business_id=p_business AND user_id=p_subject AND active;
  IF v_subject_role='investor' THEN
   RAISE EXCEPTION 'investor_cannot_receive_stock_grant'; END IF;
  SELECT active,actions INTO v_previous
   FROM core10.site_grants WHERE site_id=p_site AND user_id=p_subject;
  IF FOUND THEN
   v_before:=jsonb_build_object('active',v_previous.active,'actions',v_previous.actions);
  END IF;
  IF p_command='site_grant.grant' THEN
   INSERT INTO core10.site_grants(
    tenant_id,business_id,site_id,user_id,actions,active)
   VALUES(v_tenant,p_business,p_site,p_subject,v_actions,true)
   ON CONFLICT(site_id,user_id) DO UPDATE
    SET actions=EXCLUDED.actions,active=true;
  ELSE
   IF v_before='{}'::jsonb OR NOT v_previous.active THEN
    RAISE EXCEPTION 'site_grant_not_active'; END IF;
   UPDATE core10.site_grants SET active=false
    WHERE site_id=p_site AND user_id=p_subject;
  END IF;
  SELECT jsonb_build_object('active',active,'actions',actions) INTO v_after
   FROM core10.site_grants WHERE site_id=p_site AND user_id=p_subject;
 END IF;

 INSERT INTO core10.access_change_events_v1(
  tenant_id,business_id,request_key,command,subject_uid,
  site_id,desired_role,desired_actions,input_signature,before_state,after_state,actor_uid)
 VALUES(v_tenant,p_business,p_request,p_command,p_subject,
  p_site,p_role,NULLIF(v_actions,ARRAY[]::text[]),v_input,
  v_before,v_after,v_actor) RETURNING id INTO v_event;
 RETURN v_event;
END $function$

CREATE OR REPLACE FUNCTION core10.configure_approval_route_v1(p_policy bigint, p_stages text[], p_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE pol core10.approval_policy_versions_v1%ROWTYPE;
 old core10.approval_routes_v1%ROWTYPE;actor uuid:=core10.actor_uid();
BEGIN
 IF actor IS NULL OR p_policy IS NULL OR p_stages IS NULL
  OR cardinality(p_stages) NOT BETWEEN 2 AND 5
  OR array_position(p_stages,NULL) IS NOT NULL
  OR p_stages[1]<>'business_owner'
  OR p_stages[cardinality(p_stages)]<>'tenant_owner'
  OR NOT p_stages <@ ARRAY['business_owner','manager','tenant_owner']::text[]
  OR p_stages[1:cardinality(p_stages)-1] && ARRAY['tenant_owner']::text[]
  OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9_-]{8,128}$'
 THEN RAISE EXCEPTION 'invalid_approval_route'; END IF;
 SELECT * INTO pol FROM core10.approval_policy_versions_v1 WHERE id=p_policy FOR UPDATE;
 IF NOT FOUND OR NOT core10.can_manage(pol.tenant_id,pol.business_id)
  OR NOT core10.can_approval_action_v1(pol.tenant_id,pol.business_id,'approval.decide')
 THEN RAISE EXCEPTION 'approval_route_denied'; END IF;
 SELECT * INTO old FROM core10.approval_routes_v1 WHERE policy_id=p_policy;
 IF FOUND THEN
  IF old.configured_by<>actor OR old.stages<>p_stages OR old.route_key<>p_key
  THEN RAISE EXCEPTION 'approval_route_replay_conflict'; END IF;
  RETURN old.policy_id;
 END IF;
 IF EXISTS(SELECT 1 FROM core10.approval_requests WHERE policy_id_v1=p_policy)
 THEN RAISE EXCEPTION 'approval_route_policy_in_use'; END IF;
 INSERT INTO core10.approval_routes_v1(policy_id,tenant_id,business_id,stages,configured_by,route_key)
 VALUES(p_policy,pol.tenant_id,pol.business_id,p_stages,actor,p_key);
 PERFORM core10._append_canonical_audit_v1(pol.tenant_id,pol.business_id,
  'approval_route',p_policy::text,'approval.route',actor,'route:'||p_policy::text,
  jsonb_build_object('policy_ref',p_policy::text,'stage_count',cardinality(p_stages)));
 RETURN p_policy;
END $function$

CREATE OR REPLACE FUNCTION core10.decide_approval(p_request bigint, p_action text, p_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE q core10.approval_requests%ROWTYPE;actor uuid:=core10.actor_uid();
 prior core10.approval_events%ROWTYPE;v_stages text[];n integer;
 eligible boolean:=false;v_delegator uuid;v_event bigint;
BEGIN
 IF actor IS NULL OR p_request IS NULL OR p_action NOT IN ('approve','reject','defer')
  OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9_-]{8,128}$'
 THEN RAISE EXCEPTION 'invalid_approval_command'; END IF;
 SELECT * INTO q FROM core10.approval_requests WHERE id=p_request FOR UPDATE;
 IF NOT FOUND OR q.created_by=actor THEN RAISE EXCEPTION 'approval_not_authorized'; END IF;
 IF NOT core10.can_approval_action_v1(q.tenant_id,q.business_id,'approval.decide')
 THEN RAISE EXCEPTION 'approval_not_authorized'; END IF;
 SELECT * INTO prior FROM core10.approval_events
 WHERE request_id=p_request AND idempotency_key=p_key;
 IF FOUND THEN
  IF prior.actor_id<>actor OR prior.action<>p_action
    OR prior.tenant_id<>q.tenant_id OR prior.business_id<>q.business_id
  THEN RAISE EXCEPTION 'approval_idempotency_conflict'; END IF;
  IF NOT (core10.can_business(q.tenant_id,q.business_id) OR core10.can_tenant(q.tenant_id))
  THEN RAISE EXCEPTION 'approval_not_authorized'; END IF;
  RETURN prior.id;
 END IF;
 IF q.policy_id_v1 IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM core10.approval_policy_versions_v1 pol
   WHERE pol.id=q.policy_id_v1 AND pol.tenant_id=q.tenant_id AND pol.business_id=q.business_id
    AND pol.version=q.policy_version_v1 AND pol.domain=q.domain_v1 AND pol.action_code=q.action_code_v1)
  THEN RAISE EXCEPTION 'approval_policy_pin_invalid'; END IF;
 END IF;
 SELECT stages INTO v_stages FROM core10.approval_routes_v1
 WHERE policy_id=q.policy_id_v1;
 IF v_stages IS NULL THEN
  eligible:=core10.can_manage(q.tenant_id,q.business_id);
 ELSE
  SELECT count(*)::integer+1 INTO n FROM core10.approval_stage_receipts_v1
   WHERE request_id=p_request;
  IF n>cardinality(v_stages) THEN RAISE EXCEPTION 'approval_invalid_transition'; END IF;
  IF EXISTS(SELECT 1 FROM core10.approval_stage_receipts_v1
   WHERE request_id=p_request AND actor_id=actor)
  THEN RAISE EXCEPTION 'approval_repeated_checker'; END IF;
  eligible:=core10._can_review_stage_v1(p_request,n);
  IF eligible AND n=1 AND v_stages[1]='business_owner' THEN
   SELECT d.granted_by INTO v_delegator FROM core10.approval_delegations_v1 d
   WHERE d.request_id=p_request AND d.delegated_to=actor
     AND d.revoked_at IS NULL AND d.valid_until>statement_timestamp();
  END IF;
 END IF;
 IF NOT eligible THEN RAISE EXCEPTION 'approval_not_authorized'; END IF;
 IF q.status<>'pending' THEN RAISE EXCEPTION 'approval_invalid_transition'; END IF;
 IF q.policy_id_v1 IS NOT NULL AND q.expires_at_v1<=clock_timestamp()
 THEN RAISE EXCEPTION 'approval_expired'; END IF;
 IF v_stages IS NULL OR p_action<>'approve' OR n=cardinality(v_stages) THEN
  UPDATE core10.approval_requests SET
   status=CASE p_action WHEN 'approve' THEN 'approved'
    WHEN 'reject' THEN 'rejected' ELSE 'deferred' END,
   decided_by=actor,decided_at=clock_timestamp()
  WHERE id=p_request AND status='pending';
 END IF;
 INSERT INTO core10.approval_events(request_id,tenant_id,business_id,
   actor_id,action,idempotency_key)
 VALUES(p_request,q.tenant_id,q.business_id,actor,p_action,p_key)
 RETURNING id INTO v_event;
 IF v_stages IS NOT NULL AND p_action='approve' THEN
  INSERT INTO core10.approval_stage_receipts_v1(event_id,request_id,tenant_id,business_id,
    stage_no,actor_id,delegated_by)
  VALUES(v_event,p_request,q.tenant_id,q.business_id,n,actor,v_delegator);
 END IF;
 RETURN v_event;
END $function$

CREATE OR REPLACE FUNCTION core10.delegate_approval_stage_v1(p_request bigint, p_delegate uuid, p_minutes integer, p_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE q core10.approval_requests%ROWTYPE;d core10.approval_delegations_v1%ROWTYPE;
 actor uuid:=core10.actor_uid();event_id bigint;until_at timestamptz;
BEGIN
 IF actor IS NULL OR p_request IS NULL OR p_delegate IS NULL
  OR p_minutes IS NULL OR p_minutes NOT BETWEEN 5 AND 1440
  OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9_-]{8,128}$'
 THEN RAISE EXCEPTION 'invalid_approval_delegation'; END IF;
 SELECT * INTO q FROM core10.approval_requests WHERE id=p_request FOR UPDATE;
 IF NOT FOUND OR q.status<>'pending' OR q.policy_id_v1 IS NULL OR
    q.expires_at_v1<=clock_timestamp()
 THEN RAISE EXCEPTION 'approval_delegation_denied'; END IF;
 IF NOT core10.can_approval_action_v1(q.tenant_id,q.business_id,'approval.delegate')
   OR NOT EXISTS(SELECT 1 FROM core10.business_members m
    WHERE m.tenant_id=q.tenant_id AND m.business_id=q.business_id
      AND m.user_id=actor AND m.role='business_owner' AND m.active
      AND (m.valid_until IS NULL OR m.valid_until>statement_timestamp()))
   OR p_delegate=q.created_by OR p_delegate=actor
   OR NOT EXISTS(SELECT 1 FROM core10.business_members m
    WHERE m.tenant_id=q.tenant_id AND m.business_id=q.business_id
      AND m.user_id=p_delegate AND m.role='manager' AND m.active
      AND (m.valid_until IS NULL OR m.valid_until>statement_timestamp()))
   OR NOT EXISTS(SELECT 1 FROM core10.approval_routes_v1 r
      WHERE r.policy_id=q.policy_id_v1 AND r.stages[1]='business_owner')
   OR EXISTS(SELECT 1 FROM core10.approval_stage_receipts_v1 WHERE request_id=p_request)
 THEN RAISE EXCEPTION 'approval_delegation_denied'; END IF;
 SELECT * INTO d FROM core10.approval_delegations_v1
 WHERE request_id=p_request AND stage_no=1;
 IF FOUND THEN
  IF d.granted_by<>actor OR d.delegated_to<>p_delegate
     OR d.delegation_key<>p_key OR d.revoked_at IS NOT NULL
  THEN RAISE EXCEPTION 'approval_delegation_replay_conflict'; END IF;
  SELECT id INTO event_id FROM core10.approval_events
  WHERE request_id=p_request AND idempotency_key=p_key AND action='delegate';
  RETURN event_id;
 END IF;
 until_at:=LEAST(q.expires_at_v1,clock_timestamp()+make_interval(mins=>p_minutes));
 IF until_at<=clock_timestamp() THEN RAISE EXCEPTION 'approval_delegation_expired'; END IF;
 INSERT INTO core10.approval_delegations_v1(request_id,tenant_id,business_id,
  granted_by,delegated_to,delegation_key,valid_until)
 VALUES(p_request,q.tenant_id,q.business_id,actor,p_delegate,p_key,until_at);
 INSERT INTO core10.approval_events(request_id,tenant_id,business_id,actor_id,action,idempotency_key)
 VALUES(p_request,q.tenant_id,q.business_id,actor,'delegate',p_key) RETURNING id INTO event_id;
 RETURN event_id;
END $function$

CREATE OR REPLACE FUNCTION core10.owner_access_metric_v1(p_business bigint, p_metric text)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE v_tenant bigint;v_count bigint;
BEGIN
 SELECT tenant_id INTO v_tenant FROM core10.businesses WHERE id=p_business;
 IF v_tenant IS NULL OR NOT core10.can_manage(v_tenant,p_business)
 THEN RAISE EXCEPTION 'access_summary_not_authorized'; END IF;
 CASE p_metric
  WHEN 'business_owner' THEN
   SELECT count(*) INTO v_count FROM core10.business_members
    WHERE business_id=p_business AND active AND role='business_owner';
  WHEN 'manager' THEN
   SELECT count(*) INTO v_count FROM core10.business_members
    WHERE business_id=p_business AND active AND role='manager';
  WHEN 'investor' THEN
   SELECT count(*) INTO v_count FROM core10.business_members
    WHERE business_id=p_business AND active AND role='investor';
  WHEN 'site_grant' THEN
   SELECT count(*) INTO v_count FROM core10.site_grants
    WHERE business_id=p_business AND active;
  WHEN 'access_change' THEN
   SELECT count(*) INTO v_count FROM core10.access_change_events_v1
    WHERE business_id=p_business;
  ELSE RAISE EXCEPTION 'invalid_access_metric';
 END CASE;
 RETURN v_count;
END $function$

CREATE OR REPLACE FUNCTION core10.post_stock_event(p_location bigint, p_item bigint, p_delta numeric, p_request text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE v_loc record;v_id bigint;v_prev record;
BEGIN
 IF p_delta IS NULL OR p_delta=0 OR p_request IS NULL OR btrim(p_request)='' THEN RAISE EXCEPTION 'invalid_stock_event'; END IF;
 SELECT tenant_id,business_id,site_id INTO v_loc FROM stock_locations WHERE id=p_location;
 IF NOT FOUND OR NOT can_site(v_loc.tenant_id,v_loc.business_id,v_loc.site_id,'stock.post') THEN
  RAISE EXCEPTION 'stock_post_not_authorized';
 END IF;
 INSERT INTO stock_movements(tenant_id,business_id,site_id,location_id,item_id,delta,request_key)
 VALUES(v_loc.tenant_id,v_loc.business_id,v_loc.site_id,p_location,p_item,p_delta,p_request)
 ON CONFLICT(location_id,request_key) DO NOTHING RETURNING id INTO v_id;
 IF v_id IS NULL THEN
  SELECT id,item_id,delta,created_by INTO v_prev FROM stock_movements
   WHERE location_id=p_location AND request_key=p_request;
  IF NOT FOUND OR v_prev.item_id<>p_item OR v_prev.delta<>p_delta OR v_prev.created_by<>actor_uid()
   THEN RAISE EXCEPTION 'idempotency_key_payload_conflict'; END IF;
  v_id:=v_prev.id;
 END IF;
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION core10.provision_business(p_legal bigint, p_slug text, p_template text, p_request text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE v_tenant bigint; v_id bigint; v_existing record;
BEGIN
 IF p_slug IS NULL OR btrim(p_slug)='' OR p_request IS NULL OR btrim(p_request)='' THEN
  RAISE EXCEPTION 'invalid_business_request';
 END IF;
 SELECT tenant_id INTO v_tenant FROM legal_entities WHERE id=p_legal;
 IF v_tenant IS NULL OR NOT can_tenant(v_tenant) THEN RAISE EXCEPTION 'business_provision_not_authorized'; END IF;
 IF NOT EXISTS (SELECT 1 FROM templates t WHERE t.code=p_template AND t.demo_allowed) THEN
  RAISE EXCEPTION 'business_template_not_implemented';
 END IF;
 INSERT INTO businesses(tenant_id,legal_entity_id,slug,template_code,request_key,status)
 VALUES(v_tenant,p_legal,p_slug,p_template,p_request,'draft')
 ON CONFLICT(tenant_id,request_key) DO NOTHING RETURNING id INTO v_id;
 IF v_id IS NULL THEN
  SELECT id,legal_entity_id,slug,template_code INTO v_existing
   FROM businesses WHERE tenant_id=v_tenant AND request_key=p_request;
  IF NOT FOUND OR v_existing.legal_entity_id<>p_legal OR v_existing.slug<>p_slug OR v_existing.template_code<>p_template THEN
   RAISE EXCEPTION 'idempotency_key_payload_conflict';
  END IF;
  v_id:=v_existing.id;
 END IF;
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION core10.provision_site(p_business bigint, p_kind text, p_label text, p_request text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE v_tenant bigint;v_id bigint;v_prev record;
BEGIN
 IF p_kind NOT IN ('showroom','factory','godown','warehouse','project') OR
  p_label IS NULL OR btrim(p_label)='' OR p_request IS NULL OR btrim(p_request)='' THEN
  RAISE EXCEPTION 'invalid_site_request';
 END IF;
 SELECT tenant_id INTO v_tenant FROM businesses WHERE id=p_business;
 IF v_tenant IS NULL OR NOT can_manage(v_tenant,p_business) THEN RAISE EXCEPTION 'site_provision_not_authorized'; END IF;
 INSERT INTO sites(tenant_id,business_id,kind,label,request_key)
 VALUES(v_tenant,p_business,p_kind,p_label,p_request)
 ON CONFLICT(business_id,request_key) DO NOTHING RETURNING id INTO v_id;
 IF v_id IS NULL THEN
  SELECT id,kind,label INTO v_prev FROM sites WHERE business_id=p_business AND request_key=p_request;
  IF NOT FOUND OR v_prev.kind<>p_kind OR v_prev.label<>p_label THEN RAISE EXCEPTION 'idempotency_key_payload_conflict'; END IF;
  v_id:=v_prev.id;
 END IF;
 INSERT INTO stock_locations(tenant_id,business_id,site_id,code)
 VALUES(v_tenant,p_business,v_id,'MAIN')
 ON CONFLICT(site_id,code) DO NOTHING;
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION core10.publish_approval_policy_v1(p_business bigint, p_domain text, p_action text, p_ttl_minutes integer, p_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE
  v_tenant bigint;
  v_actor uuid := core10.actor_uid();
  v_version integer;
  v_id bigint;
  v_old core10.approval_policy_versions_v1%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR p_business IS NULL
    OR p_domain IS NULL OR p_domain !~ '^[a-z][a-z0-9_]{1,63}$'
    OR p_action IS NULL OR p_action !~ '^[a-z][a-z0-9_]{1,63}$'
    OR p_ttl_minutes IS NULL OR p_ttl_minutes NOT BETWEEN 5 AND 43200
    OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9_-]{8,128}$'
  THEN RAISE EXCEPTION 'invalid_approval_policy'; END IF;

  -- Serialize version allocation for this business, including concurrent owners.
  SELECT tenant_id INTO v_tenant
    FROM core10.businesses WHERE id = p_business FOR UPDATE;
  IF NOT FOUND OR NOT core10.can_manage(v_tenant, p_business)
  THEN RAISE EXCEPTION 'approval_policy_denied'; END IF;

  SELECT * INTO v_old FROM core10.approval_policy_versions_v1
    WHERE business_id = p_business AND request_key = p_key;
  IF FOUND THEN
    IF v_old.created_by <> v_actor OR v_old.domain <> p_domain
      OR v_old.action_code <> p_action OR v_old.ttl_minutes <> p_ttl_minutes
    THEN RAISE EXCEPTION 'approval_policy_replay_conflict'; END IF;
    RETURN v_old.id;
  END IF;

  SELECT COALESCE(max(version), 0) + 1 INTO v_version
    FROM core10.approval_policy_versions_v1
    WHERE business_id = p_business AND domain = p_domain
      AND action_code = p_action;

  INSERT INTO core10.approval_policy_versions_v1
    (tenant_id, business_id, domain, action_code, version,
     ttl_minutes, request_key, created_by)
  VALUES (v_tenant, p_business, p_domain, p_action, v_version,
          p_ttl_minutes, p_key, v_actor)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION core10.revoke_approval_delegation_v1(p_request bigint, p_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE q core10.approval_requests%ROWTYPE;d core10.approval_delegations_v1%ROWTYPE;
 actor uuid:=core10.actor_uid();event_id bigint;
BEGIN
 IF actor IS NULL OR p_request IS NULL OR p_key IS NULL
    OR p_key !~ '^[A-Za-z0-9_-]{8,128}$'
 THEN RAISE EXCEPTION 'invalid_approval_revocation'; END IF;
 SELECT * INTO q FROM core10.approval_requests WHERE id=p_request FOR UPDATE;
 SELECT * INTO d FROM core10.approval_delegations_v1 WHERE request_id=p_request;
 IF q.id IS NULL OR d.id IS NULL OR
    NOT (d.granted_by=actor OR core10.can_tenant(q.tenant_id))
    OR NOT core10.can_approval_action_v1(q.tenant_id,q.business_id,'approval.delegate')
 THEN RAISE EXCEPTION 'approval_revocation_denied'; END IF;
 SELECT id INTO event_id FROM core10.approval_events
 WHERE request_id=p_request AND idempotency_key=p_key AND actor_id=actor AND action='revoke';
 IF FOUND THEN RETURN event_id; END IF;
 IF d.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'approval_delegation_already_revoked'; END IF;
 UPDATE core10.approval_delegations_v1
 SET revoked_at=clock_timestamp(),revoked_by=actor WHERE id=d.id;
 INSERT INTO core10.approval_events(request_id,tenant_id,business_id,actor_id,action,idempotency_key)
 VALUES(p_request,q.tenant_id,q.business_id,actor,'revoke',p_key) RETURNING id INTO event_id;
 RETURN event_id;
END $function$

CREATE OR REPLACE FUNCTION core10.setup_business_v1(p_legal bigint, p_slug text, p_template text, p_display_name text, p_mode text, p_sites jsonb, p_request text, p_brand_hex text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE v_tenant bigint;v_business bigint;v_sites jsonb;v_manifest jsonb;
 v_prev record;v_site jsonb;v_kind text;v_label text;v_ix integer:=0;
 v_site_signatures text[]:='{}';v_sig text;
BEGIN
 IF core10.actor_uid() IS NULL OR
    p_slug IS NULL OR length(btrim(p_slug)) NOT BETWEEN 1 AND 80 OR
    p_display_name IS NULL OR length(btrim(p_display_name)) NOT BETWEEN 1 AND 120 OR
    p_request IS NULL OR length(btrim(p_request)) NOT BETWEEN 1 AND 120 OR
    p_mode NOT IN('quick','advanced') OR p_mode IS NULL OR
    p_brand_hex IS NULL OR p_brand_hex !~ '^#[A-Fa-f0-9]{6}$' THEN
  RAISE EXCEPTION 'invalid_setup_request';
 END IF;
 SELECT tenant_id INTO v_tenant FROM core10.legal_entities WHERE id=p_legal;
 IF v_tenant IS NULL OR NOT core10.can_tenant(v_tenant) THEN
  RAISE EXCEPTION 'setup_not_authorized';
 END IF;
 IF p_mode='quick' THEN
  IF p_sites IS NOT NULL AND p_sites<>'[]'::jsonb THEN
   RAISE EXCEPTION 'quick_setup_does_not_accept_custom_sites';
  END IF;
  v_sites:='[{"kind":"showroom","label":"Main Showroom"}]'::jsonb;
 ELSE
  IF p_sites IS NULL OR jsonb_typeof(p_sites)<>'array' OR
    jsonb_array_length(p_sites)<1 OR jsonb_array_length(p_sites)>500 THEN
   RAISE EXCEPTION 'invalid_advanced_sites';
  END IF;
  v_sites:=p_sites;
 END IF;
 FOR v_site IN SELECT value FROM jsonb_array_elements(v_sites) LOOP
  v_ix:=v_ix+1;
  IF jsonb_typeof(v_site)<>'object' OR
    (SELECT count(*) FROM jsonb_object_keys(v_site))<>2 THEN
   RAISE EXCEPTION 'invalid_site_manifest';
  END IF;
  v_kind:=v_site->>'kind';
  v_label:=v_site->>'label';
  IF v_kind IS NULL OR v_kind NOT IN ('showroom','factory','godown','warehouse','project') OR
    v_label IS NULL OR length(btrim(v_label)) NOT BETWEEN 1 AND 120 THEN
   RAISE EXCEPTION 'invalid_site_manifest';
  END IF;
  v_sig:=v_kind||':'||lower(btrim(v_label));
  IF v_sig=ANY(v_site_signatures) THEN RAISE EXCEPTION 'duplicate_site_manifest'; END IF;
  v_site_signatures:=array_append(v_site_signatures,v_sig);
 END LOOP;
 v_manifest:=jsonb_build_object('legal',p_legal,'slug',p_slug,
  'template',p_template,'display_name',p_display_name,'mode',p_mode,
  'sites',v_sites,'brand_hex',p_brand_hex);

 SELECT business_id,payload,created_by INTO v_prev
 FROM core10.business_setup_runs_v1
 WHERE tenant_id=v_tenant AND request_key=p_request;
 IF FOUND THEN
  IF v_prev.payload<>v_manifest OR v_prev.created_by<>core10.actor_uid() THEN
   RAISE EXCEPTION 'idempotency_key_payload_conflict';
  END IF;
  RETURN v_prev.business_id;
 END IF;
 -- All rows are in the caller's single database transaction; any bad site
 -- or retry conflict rolls back business, locations, config, modules and run.
 v_business:=core10.provision_business(
   p_legal,p_slug,p_template,'setup:'||p_request);
 INSERT INTO core10.business_configuration_v1(
    business_id,tenant_id,display_name,brand_hex,setup_mode,setup_status,created_by)
 VALUES(v_business,v_tenant,p_display_name,p_brand_hex,p_mode,'draft',core10.actor_uid())
 ON CONFLICT(business_id) DO NOTHING;
 SELECT display_name,brand_hex,setup_mode,created_by INTO v_prev
  FROM core10.business_configuration_v1 WHERE business_id=v_business;
 IF v_prev.display_name<>p_display_name OR v_prev.brand_hex<>p_brand_hex OR
   v_prev.setup_mode<>p_mode OR v_prev.created_by<>core10.actor_uid() THEN
  RAISE EXCEPTION 'business_config_conflict';
 END IF;
 v_ix:=0;
 FOR v_site IN SELECT value FROM jsonb_array_elements(v_sites) LOOP
  v_ix:=v_ix+1;
  PERFORM core10.provision_site(v_business,v_site->>'kind',v_site->>'label',
    'setup:'||p_request||':site:'||lpad(v_ix::text,4,'0'));
 END LOOP;
 INSERT INTO core10.business_module_settings_v1(
    tenant_id,business_id,module_code,visibility,operational_enabled)
 SELECT v_tenant,v_business,tm.module_code,'locked',false
 FROM core10.template_modules_v1 tm WHERE tm.template_code=p_template
 ON CONFLICT(business_id,module_code) DO NOTHING;
 INSERT INTO core10.business_setup_runs_v1(
    tenant_id,business_id,request_key,payload,created_by)
 VALUES(v_tenant,v_business,p_request,v_manifest,core10.actor_uid())
 ON CONFLICT(tenant_id,request_key) DO NOTHING;
 SELECT business_id,payload,created_by INTO v_prev FROM core10.business_setup_runs_v1
 WHERE tenant_id=v_tenant AND request_key=p_request;
 IF v_prev.business_id<>v_business OR v_prev.payload<>v_manifest OR
   v_prev.created_by<>core10.actor_uid() THEN
  RAISE EXCEPTION 'idempotency_key_payload_conflict';
 END IF;
 RETURN v_business;
END $function$

CREATE OR REPLACE FUNCTION core10.setup_industry_draft_v2(p_legal bigint, p_slug text, p_template_id text, p_display_name text, p_mode text, p_sites jsonb, p_modules jsonb, p_request text, p_brand_hex text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE
 v_tenant bigint;v_business bigint;v_prev record;v_manifest jsonb;
 v_sites jsonb;v_site jsonb;v_mod text;v_modules text[]:=ARRAY[]::text[];
 v_signatures text[]:=ARRAY[]::text[];v_sig text;v_ix int:=0;v_request text;
BEGIN
 IF core10.actor_uid() IS NULL OR
   p_legal IS NULL OR p_template_id IS NULL OR
   p_slug IS NULL OR p_slug !~ '^[a-z][a-z0-9-]{0,79}$' OR
   p_display_name IS NULL OR length(btrim(p_display_name)) NOT BETWEEN 1 AND 120 OR
   p_mode IS NULL OR p_mode NOT IN ('quick','advanced') OR
   p_request IS NULL OR length(btrim(p_request)) NOT BETWEEN 1 AND 110 OR
   p_brand_hex IS NULL OR p_brand_hex !~ '^#[0-9A-Fa-f]{6}$' THEN
  RAISE EXCEPTION 'invalid_industry_setup';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM core10.industry_catalog_v2 WHERE id=p_template_id) THEN
  RAISE EXCEPTION 'unknown_industry_template';
 END IF;
 SELECT tenant_id INTO v_tenant FROM core10.legal_entities WHERE id=p_legal;
 IF v_tenant IS NULL OR NOT core10.can_tenant(v_tenant) THEN
  RAISE EXCEPTION 'industry_setup_not_authorized';
 END IF;
 IF p_modules IS NULL OR jsonb_typeof(p_modules)<>'array' OR jsonb_array_length(p_modules)>100 THEN
  RAISE EXCEPTION 'invalid_module_manifest';
 END IF;
 FOR v_mod IN SELECT value FROM jsonb_array_elements_text(p_modules) LOOP
  IF v_mod IS NULL OR v_mod=ANY(v_modules) OR NOT EXISTS(
   SELECT 1 FROM core10.industry_module_catalog_v2
   WHERE industry_id=p_template_id AND module_code=v_mod) THEN
   RAISE EXCEPTION 'invalid_module_manifest';
  END IF;
  v_modules:=array_append(v_modules,v_mod);
 END LOOP;
 IF p_mode='quick' THEN
  IF p_sites IS NOT NULL AND p_sites<>'[]'::jsonb THEN RAISE EXCEPTION 'quick_custom_sites_denied'; END IF;
  v_sites:='[{"kind":"showroom","label":"Main Showroom"}]'::jsonb;
 ELSE
  IF p_sites IS NULL OR jsonb_typeof(p_sites)<>'array' OR
    jsonb_array_length(p_sites) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'invalid_industry_sites';
  END IF;
  v_sites:=p_sites;
 END IF;
 FOR v_site IN SELECT value FROM jsonb_array_elements(v_sites) LOOP
  IF jsonb_typeof(v_site)<>'object' OR
    (SELECT count(*) FROM jsonb_object_keys(v_site))<>2 OR
    coalesce(v_site->>'kind','') NOT IN ('showroom','factory','godown','warehouse','project') OR
    length(btrim(coalesce(v_site->>'label',''))) NOT BETWEEN 1 AND 120 THEN
   RAISE EXCEPTION 'invalid_industry_sites';
  END IF;
  v_sig:=v_site->>'kind'||':'||lower(btrim(v_site->>'label'));
  IF v_sig=ANY(v_signatures) THEN RAISE EXCEPTION 'duplicate_industry_site'; END IF;
  v_signatures:=array_append(v_signatures,v_sig);
 END LOOP;
 v_request:='industry-v2:'||p_request;
 v_manifest:=jsonb_build_object('legal',p_legal,'slug',p_slug,'template',p_template_id,
    'name',p_display_name,'mode',p_mode,'sites',v_sites,'modules',to_jsonb(v_modules),
    'brand',p_brand_hex);
 SELECT business_id,payload,created_by INTO v_prev
 FROM core10.business_setup_runs_v1
 WHERE tenant_id=v_tenant AND request_key=v_request;
 IF FOUND THEN
  IF v_prev.payload<>v_manifest OR v_prev.created_by<>core10.actor_uid() THEN
   RAISE EXCEPTION 'idempotency_key_payload_conflict';
  END IF;
  RETURN v_prev.business_id;
 END IF;
 INSERT INTO core10.businesses(tenant_id,legal_entity_id,slug,template_code,request_key,status)
 VALUES(v_tenant,p_legal,p_slug,p_template_id,v_request,'draft')
 ON CONFLICT(tenant_id,request_key) DO NOTHING RETURNING id INTO v_business;
 IF v_business IS NULL THEN
  SELECT id,legal_entity_id,slug,template_code INTO v_prev FROM core10.businesses
  WHERE tenant_id=v_tenant AND request_key=v_request;
  IF NOT FOUND OR v_prev.legal_entity_id<>p_legal OR v_prev.slug<>p_slug OR
    v_prev.template_code<>p_template_id THEN
   RAISE EXCEPTION 'idempotency_key_payload_conflict';
  END IF;
  v_business:=v_prev.id;
 END IF;
 INSERT INTO core10.business_configuration_v1(
  business_id,tenant_id,display_name,brand_hex,setup_mode,setup_status,created_by)
 VALUES(v_business,v_tenant,p_display_name,p_brand_hex,p_mode,'draft',core10.actor_uid())
 ON CONFLICT(business_id) DO NOTHING;
 SELECT display_name,brand_hex,setup_mode,created_by INTO v_prev FROM core10.business_configuration_v1
 WHERE business_id=v_business;
 IF v_prev.display_name<>p_display_name OR v_prev.brand_hex<>p_brand_hex OR
    v_prev.setup_mode<>p_mode OR v_prev.created_by<>core10.actor_uid() THEN
   RAISE EXCEPTION 'idempotency_key_payload_conflict';
 END IF;
 FOR v_site IN SELECT value FROM jsonb_array_elements(v_sites) LOOP
  v_ix:=v_ix+1;
  PERFORM core10.provision_site(v_business,v_site->>'kind',v_site->>'label',
    v_request||':site:'||lpad(v_ix::text,4,'0'));
 END LOOP;
 INSERT INTO core10.business_module_settings_v1(
   tenant_id,business_id,module_code,visibility,operational_enabled)
 SELECT v_tenant,v_business,mod,'locked',false FROM unnest(v_modules) AS mod
 ON CONFLICT(business_id,module_code) DO NOTHING;
 INSERT INTO core10.business_setup_runs_v1(
   tenant_id,business_id,request_key,payload,created_by)
 VALUES(v_tenant,v_business,v_request,v_manifest,core10.actor_uid())
 ON CONFLICT(tenant_id,request_key) DO NOTHING;
 SELECT business_id,payload,created_by INTO v_prev FROM core10.business_setup_runs_v1
 WHERE tenant_id=v_tenant AND request_key=v_request;
 IF v_prev.business_id<>v_business OR v_prev.payload<>v_manifest OR
    v_prev.created_by<>core10.actor_uid() THEN
   RAISE EXCEPTION 'idempotency_key_payload_conflict';
 END IF;
 RETURN v_business;
END $function$

CREATE OR REPLACE FUNCTION core10.submit_typed_approval_v1(p_business bigint, p_domain text, p_action text, p_source_key text, p_source_version bigint, p_payload jsonb, p_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'core10', 'pg_catalog'
AS $function$
DECLARE
  v_tenant bigint;
  v_actor uuid := core10.actor_uid();
  v_policy core10.approval_policy_versions_v1%ROWTYPE;
  v_digest text;
  v_id bigint;
  v_old core10.approval_requests%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR p_business IS NULL
    OR p_domain IS NULL OR p_domain !~ '^[a-z][a-z0-9_]{1,63}$'
    OR p_action IS NULL OR p_action !~ '^[a-z][a-z0-9_]{1,63}$'
    OR p_source_key IS NULL OR length(btrim(p_source_key)) NOT BETWEEN 1 AND 160
    OR p_source_version IS NULL OR p_source_version <= 0
    OR p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object'
    OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9_-]{8,128}$'
  THEN RAISE EXCEPTION 'invalid_typed_approval_request'; END IF;

  SELECT tenant_id INTO v_tenant FROM core10.businesses WHERE id = p_business;
  IF NOT FOUND OR NOT core10.can_business(v_tenant, p_business)
  THEN RAISE EXCEPTION 'approval_submit_denied'; END IF;

  -- Normalize JSONB and compute SHA256 at the server; no client-supplied digest.
  v_digest := encode(sha256(convert_to(p_payload::text, 'UTF8')), 'hex');

  -- Replay is bound to the FIRST policy version even after Owner publishes a new one.
  SELECT * INTO v_old FROM core10.approval_requests
    WHERE business_id = p_business AND created_by = v_actor AND submit_key_v1 = p_key;
  IF FOUND THEN
    IF v_old.domain_v1 IS DISTINCT FROM p_domain
      OR v_old.action_code_v1 IS DISTINCT FROM p_action
      OR v_old.source_key_v1 IS DISTINCT FROM btrim(p_source_key)
      OR v_old.source_version_v1 IS DISTINCT FROM p_source_version
      OR v_old.payload_sha256_v1 IS DISTINCT FROM v_digest
    THEN RAISE EXCEPTION 'approval_submit_replay_conflict'; END IF;
    RETURN v_old.id;
  END IF;

  SELECT * INTO v_policy FROM core10.approval_policy_versions_v1
    WHERE tenant_id = v_tenant AND business_id = p_business
      AND domain = p_domain AND action_code = p_action
    ORDER BY version DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'approval_policy_missing'; END IF;

  INSERT INTO core10.approval_requests
    (tenant_id, business_id, created_by, domain_v1, action_code_v1,
     source_key_v1, source_version_v1, payload_sha256_v1,
     policy_id_v1, policy_version_v1, expires_at_v1, submit_key_v1)
  VALUES
    (v_tenant, p_business, v_actor, p_domain, p_action,
     btrim(p_source_key), p_source_version, v_digest,
     v_policy.id, v_policy.version,
     clock_timestamp() + make_interval(mins => v_policy.ttl_minutes), p_key)
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT * INTO v_old FROM core10.approval_requests
      WHERE business_id = p_business AND created_by = v_actor AND submit_key_v1 = p_key;
    IF NOT FOUND
      OR v_old.domain_v1 IS DISTINCT FROM p_domain
      OR v_old.action_code_v1 IS DISTINCT FROM p_action
      OR v_old.source_key_v1 IS DISTINCT FROM btrim(p_source_key)
      OR v_old.source_version_v1 IS DISTINCT FROM p_source_version
      OR v_old.payload_sha256_v1 IS DISTINCT FROM v_digest
    THEN RAISE EXCEPTION 'approval_submit_replay_conflict'; END IF;
    v_id := v_old.id;
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION core10.verify_canonical_audit_v1(p_business bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE h core10.audit_chain_heads_v1%ROWTYPE; e record;
 v_prior text:=repeat('0',64);v_n bigint:=0;v_sha text;v_digest text;v_tenant bigint;
BEGIN
 SELECT tenant_id INTO v_tenant FROM core10.businesses WHERE id=p_business;
 IF v_tenant IS NULL OR NOT core10.can_manage(v_tenant,p_business)
 THEN RAISE EXCEPTION 'canonical_audit_read_denied'; END IF;
 FOR e IN SELECT * FROM core10.canonical_audit_events_v1
   WHERE business_id=p_business ORDER BY stream_seq LOOP
  v_n:=v_n+1;
  IF e.stream_seq<>v_n OR e.prior_digest<>v_prior THEN
   RETURN jsonb_build_object('ok',false,'checked',v_n,'reason','chain_gap'); END IF;
  v_sha:=encode(sha256(convert_to(e.payload::text,'UTF8')),'hex');
  v_digest:=encode(sha256(convert_to(concat_ws('|',
    'c10-audit-v1',v_prior,e.tenant_id::text,e.business_id::text,e.stream_seq::text,
    e.source_domain,e.source_ref,e.action,e.actor_id::text,e.request_key,v_sha,
    to_char(e.event_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),'UTF8')),'hex');
  IF v_sha<>e.payload_sha256 OR v_digest<>e.event_digest THEN
   RETURN jsonb_build_object('ok',false,'checked',v_n,'reason','digest_mismatch'); END IF;
  v_prior:=e.event_digest;
 END LOOP;
 SELECT * INTO h FROM core10.audit_chain_heads_v1 WHERE business_id=p_business;
 IF (NOT FOUND AND v_n>0) OR
    (FOUND AND (h.last_seq<>v_n OR h.last_digest<>v_prior OR h.tenant_id<>v_tenant)) THEN
  RETURN jsonb_build_object('ok',false,'checked',v_n,'reason','head_mismatch'); END IF;
 RETURN jsonb_build_object('ok',true,'checked',v_n,'reason',null);
END $function$

CREATE OR REPLACE FUNCTION core10.withdraw_typed_approval_v1(p_request bigint, p_key text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'core10'
AS $function$
DECLARE q core10.approval_requests%ROWTYPE;actor uuid:=core10.actor_uid();
 event_id bigint;
BEGIN
 IF actor IS NULL OR p_request IS NULL OR p_key IS NULL
  OR p_key !~ '^[A-Za-z0-9_-]{8,128}$'
 THEN RAISE EXCEPTION 'invalid_approval_withdrawal'; END IF;
 SELECT * INTO q FROM core10.approval_requests WHERE id=p_request FOR UPDATE;
 IF NOT FOUND OR q.policy_id_v1 IS NULL OR q.created_by<>actor
  OR NOT core10.can_approval_action_v1(q.tenant_id,q.business_id,'approval.withdraw')
 THEN RAISE EXCEPTION 'approval_withdraw_denied'; END IF;
 SELECT id INTO event_id FROM core10.approval_events
 WHERE request_id=p_request AND idempotency_key=p_key AND action='withdraw' AND actor_id=actor;
 IF FOUND THEN RETURN event_id; END IF;
 IF q.status<>'pending' OR EXISTS(SELECT 1 FROM core10.approval_stage_receipts_v1
  WHERE request_id=p_request)
 THEN RAISE EXCEPTION 'withdraw_invalid_transition'; END IF;
 UPDATE core10.approval_requests SET status='withdrawn',decided_by=actor,
   decided_at=clock_timestamp() WHERE id=p_request;
 INSERT INTO core10.approval_events(request_id,tenant_id,business_id,actor_id,action,idempotency_key)
 VALUES(p_request,q.tenant_id,q.business_id,actor,'withdraw',p_key)
 RETURNING id INTO event_id;
 RETURN event_id;
END $function$
